// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/setting-up-shaders-in-p5


//Interpolation//
let xx=0, nx =0;
let yy=0, ny=0;

let theShader;
let WebGL;
let Canvas;
let img;

function preload(){
  theShader = createShader(vert, frag);
	img = loadImage('https://openprocessing.org/sketch/2080440/files/Map.png');
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  WebGL = createGraphics(100, 1000, WEBGL);
  Canvas = createGraphics(width, height);
  noStroke();
}

function draw() {

	  //Interpolation//
  if(frameCount%20 == 0){
    nx=random(0, width);
    ny=random(0, height);
  }

  xx += (nx - xx) * 0.1;
  yy += (ny - yy) * 0.4;


	WebGL.shader(theShader);

  theShader.setUniform('iResolution', [width, height]);
	theShader.setUniform('iPixelDensity', pixelDensity());
	theShader.setUniform('iCanvas', Canvas);
	theShader.setUniform('iImage', img);
	theShader.setUniform('iImageResolution', [img.width, img.height]);
  theShader.setUniform('iMouse', [xx, yy]);
  theShader.setUniform('iTime', frameCount);

  WebGL.rect(0, 0, width, height);

  image(WebGL, 1000, 1000);
}

